import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.RQXGjTIX.js";const o="/appliedcraftedenergistics/gui-interface.png",b=JSON.parse('{"title":"ME 气体接口","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interface.md","filePath":"guide/interface.md"}'),s={name:"guide/interface.md"};function n(i,t,l,c,h,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="me-气体接口" tabindex="-1">ME 气体接口 <a class="header-anchor" href="#me-气体接口" aria-label="Permalink to &quot;ME 气体接口&quot;">​</a></h1><p>0.2.2 起，ME 气体接口是 AE2 原版 ME 接口的<strong>气体增强版</strong>：九组「配置槽 + 缓存槽」、逐槽目标数量与目标压力、逐槽传输模式，以及两种接口专用升级卡。</p><p><img src="'+o+`" alt="ME 气体接口 GUI"></p><h2 id="九组配置槽与缓存槽" tabindex="-1">九组配置槽与缓存槽 <a class="header-anchor" href="#九组配置槽与缓存槽" aria-label="Permalink to &quot;九组配置槽与缓存槽&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>说明</th></tr></thead><tbody><tr><td>上排（配置槽 ×9）</td><td>标记气体种类、目标数量、目标压力与模式</td></tr><tr><td>下排（缓存槽 ×9）</td><td>显示该槽当前缓存；由 AE2 网络按目标数量自动补货</td></tr><tr><td>每槽上限</td><td><strong>64kGU</strong>（64,000 GU），九槽理论总容量 576kGU</td></tr><tr><td>每槽气体</td><td>只能缓存一种气体</td></tr></tbody></table><p>接口每 tick 检查九个槽位：低于目标数量就从网络补货；超过目标数量、或槽位未配置时，把多余气体退回网络。目标数量是<strong>缓存上限</strong>，不是累计输出总量——槽位可以反复补货，向外部管网累计供应远超 64kGU 的气体。</p><div class="tip custom-block"><p class="custom-block-title">未配置的槽位</p><p>没有标记气体的槽位不会长期缓存：CCB 管道送入的气体会在下一个 tick 被接口收进 ME 网络（与原版 ME 接口“自动识别”的行为一致）。</p></div><h2 id="逐槽设置" tabindex="-1">逐槽设置 <a class="header-anchor" href="#逐槽设置" aria-label="Permalink to &quot;逐槽设置&quot;">​</a></h2><p>每个已标记的配置槽上方都有<strong>设置按钮</strong>；也可以<strong>中键点击</strong>配置槽打开逐槽设置界面。界面提供：</p><ul><li><strong>目标数量</strong>：数字输入框，按 GU 设置该槽缓存上限；</li><li><strong>目标压力</strong>：<code>-</code> / <code>+</code> 调压，或使用 <strong>自动</strong> 返回默认压力；</li><li><strong>传输模式</strong>：安装逐槽控制卡后可选择输入 / 输出 / 双向 / 关闭。</li></ul><p>设置保存在接口的槽位数据中，不会写进配置文件。</p><h2 id="目标压力" tabindex="-1">目标压力 <a class="header-anchor" href="#目标压力" aria-label="Permalink to &quot;目标压力&quot;">​</a></h2><p>每个槽位可以单独设置目标压力（默认 1 atm，未显式配置时显示灰色默认值）。压力与目标数量共同决定槽位的<strong>真实体积</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体积(L) = 目标数量(GU) / 目标压力(atm)</span></span>
<span class="line"><span>压力   = 当前数量 × 100,000 / 体积</span></span></code></pre></div><p>因此槽位装满目标数量时，压力恰好等于目标压力；不足时压力更低，CCB 管道会按压差自然流动。槽位容器额定到 CCB 的硬上限 <strong>24 atm</strong>，但正常目标压力最高 <strong>16 atm</strong>（CCB 安全线）。</p><p><strong>接口不会无条件维持压力</strong>：实际供气受缓存数量、外部管网压力、CCB 求解器与流量上限共同约束；ME 网络仍然只以 GasKey + GU 数量管理气体，压力不进入 GasKey。</p><h2 id="传输模式与逐槽控制卡" tabindex="-1">传输模式与逐槽控制卡 <a class="header-anchor" href="#传输模式与逐槽控制卡" aria-label="Permalink to &quot;传输模式与逐槽控制卡&quot;">​</a></h2><p>默认<strong>所有槽位双向</strong>（BOTH），不需要任何升级卡。</p><p>安装 <strong>逐槽控制卡</strong>（<code>slot_control_card</code>，最多 1 张）后，每个槽位可以独立设置：</p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>输入</strong></td><td>只允许外部管网 → ME 网络</td></tr><tr><td><strong>输出</strong></td><td>只允许 ME 网络 → 外部管网</td></tr><tr><td><strong>双向</strong></td><td>两个方向都允许（默认）</td></tr><tr><td><strong>关闭</strong></td><td>该槽位不参与 CCB 传输（仍参与 ME 补货/回收）</td></tr></tbody></table><ul><li>安装卡片时所有槽位保持双向，不改变现有配置；</li><li>移除卡片后统一回到双向，逐槽设置保留在存档里，重新安装即恢复；</li><li>未安装卡片时，GUI 不会提供逐槽模式切换。</li></ul><h2 id="安全卡" tabindex="-1">安全卡 <a class="header-anchor" href="#安全卡" aria-label="Permalink to &quot;安全卡&quot;">​</a></h2><p>安装 <strong>安全卡</strong>（<code>safety_valve_card</code>，最多 1 张）后，槽位压力达到 <strong>20 atm</strong> 时自动泄压：</p><ol><li>从槽位取出一小批气体（1,000 GU/t）；</li><li>通过 CCB 的 <code>GasReleaseService</code> 做一次<strong>真实的径向释放</strong>（<code>GasReleaseCause.OVERFLOW</code>）；</li><li>只在释放成功后扣除槽内气体，释放失败不会凭空删气；</li><li>压力回落到安全范围后停止。</li></ol><p>排出的气体产生 CCB 原生环境效果（含推动附近实体），而不是简单删除数量。正常目标压力（≤16 atm）低于泄压阈值，因此不会出现“补气 → 泄压”的循环。</p><blockquote><p>注意：元件上的 <code>relief_valve_card</code> 中文名是 <strong>泄压阀卡</strong>，与本接口的 <strong>安全卡</strong> 不是同一张卡。</p></blockquote><h2 id="气体标记" tabindex="-1">气体标记 <a class="header-anchor" href="#气体标记" aria-label="Permalink to &quot;气体标记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>气体样本</td><td><code>gas_sample</code> 物品，右键配置槽写入气体</td></tr><tr><td>气体容器</td><td>手持 CCB 气罐/容器右键配置槽，读取其中气体写入</td></tr><tr><td>AE2 包裹资源</td><td>配置槽接受 AE2 的 <code>WrappedGenericStack</code>（气体键的包裹物品）</td></tr><tr><td>JEI 拖拽</td><td>安装 JEI 时，把 CCB 气体 ingredient / 气体虚拟物品拖到配置槽（0.2.1+）</td></tr></tbody></table><p>标记后目标数量默认 64kGU，可在设置界面调整。</p><h2 id="升级卡" tabindex="-1">升级卡 <a class="header-anchor" href="#升级卡" aria-label="Permalink to &quot;升级卡&quot;">​</a></h2><p>接口有 <strong>6 个升级槽</strong>：</p><table tabindex="0"><thead><tr><th>卡</th><th>上限</th><th>作用</th></tr></thead><tbody><tr><td>速度卡</td><td>4 张</td><td>提高每 tick 的网络补货/回收速度</td></tr><tr><td>逐槽控制卡</td><td>1 张</td><td>解锁逐槽输入/输出/双向/关闭</td></tr><tr><td>安全卡</td><td>1 张</td><td>过压真实排气</td></tr></tbody></table><h2 id="总线上的气体压力卡" tabindex="-1">总线上的气体压力卡 <a class="header-anchor" href="#总线上的气体压力卡" aria-label="Permalink to &quot;总线上的气体压力卡&quot;">​</a></h2><p><strong>气体压力卡</strong>（<code>gas_pressure_card</code>）不是接口卡，而是安装在 AE2 <strong>输入总线 / 输出总线</strong>里的总线升级卡：</p><ul><li>输出总线只把气体输出到目标压力；</li><li>输入总线只在外部压力高于目标压力时抽取；</li><li>右键卡循环预设，潜行右键回退。</li></ul><h2 id="gui-操作" tabindex="-1">GUI 操作 <a class="header-anchor" href="#gui-操作" aria-label="Permalink to &quot;GUI 操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td>点击配置槽上方的设置按钮</td><td>打开逐槽设置界面</td></tr><tr><td>中键点击配置槽</td><td>打开逐槽设置界面</td></tr><tr><td>右键配置槽（手持气体样本/容器）</td><td>标记气体</td></tr><tr><td>悬停配置槽</td><td>显示服务端实际保存的目标数量/压力/模式</td></tr></tbody></table><h2 id="从-0-1-x-升级" tabindex="-1">从 0.1.x 升级 <a class="header-anchor" href="#从-0-1-x-升级" aria-label="Permalink to &quot;从 0.1.x 升级&quot;">​</a></h2><ul><li>旧的 8 kL 缓冲罐气体在加载时自动转入<strong>第一个空槽</strong>；九个槽都满时按丢失处理并在日志中记录；</li><li>旧的单设备模式（导入/导出/双向/关闭）与供给压力设置不再使用，新接口默认全部双向、逐槽可调；</li><li>0.1.x 的 <code>gas_interface.bufferVolumeLiters</code>、<code>supplyPressureKpa</code>、<code>transferRate</code>、<code>energyPerKiloGasUnit</code> 配置项废弃。</li></ul><div class="tip custom-block"><p class="custom-block-title">AE2 原版 ME 接口</p><p>0.2.2 通过 <code>AeInterfaceGasCompat</code> 为原版 <code>ae2:interface</code> 重新注册气体能力：CCB 管道可以从接口槽位抽气。 ACE 自己的 ME 气体接口仍提供逐槽压力、模式与缓存控制。</p></div>`,40)])])}const u=e(s,[["render",n]]);export{b as __pageData,u as default};
